--
-- Table structure for table `edu_schedule_log`
--

DROP TABLE IF EXISTS `edu_schedule_log`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `edu_schedule_log` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `tenant_id` bigint DEFAULT '0' COMMENT '租户ID',
  `schedule_id` bigint NOT NULL COMMENT '课次ID',
  `op_type` varchar(20) NOT NULL COMMENT '操作类型：排课/调课/取消排课/补课',
  `operator` varchar(50) DEFAULT NULL COMMENT '操作人（登录账号用户名）',
  `op_time` datetime DEFAULT NULL COMMENT '操作时间',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注（调课/取消原因）',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '入库时间',
  `course_name` varchar(100) DEFAULT NULL COMMENT '课程快照（课次删除后历史展示）',
  `teacher_name` varchar(50) DEFAULT NULL COMMENT '教师快照',
  `classroom` varchar(50) DEFAULT NULL COMMENT '教室快照',
  `class_time` varchar(60) DEFAULT NULL COMMENT '上课时间快照',
  PRIMARY KEY (`id`),
  KEY `idx_schedule` (`schedule_id`),
  KEY `idx_op_time` (`op_time`)
) ENGINE=InnoDB AUTO_INCREMENT=124 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='排课操作日志';
/*!40101 SET character_set_client = @saved_cs_client */;

