--
-- Table structure for table `edu_student`
--

DROP TABLE IF EXISTS `edu_student`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `edu_student` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint NOT NULL,
  `user_id` bigint DEFAULT NULL COMMENT '关联登录账号',
  `name` varchar(32) COLLATE utf8mb4_general_ci NOT NULL,
  `gender` tinyint DEFAULT '1' COMMENT '1男 2女',
  `birth_date` date DEFAULT NULL,
  `school` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '就读学校(统计维度)',
  `grade` varchar(32) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '年级',
  `id_card` varchar(18) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '身份证号',
  `parent_name` varchar(32) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `parent_phone` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `address` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `remark` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP,
  `backup_phone` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '备用电话',
  `advisor` varchar(32) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '归属顾问',
  `tags` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '学员标签逗号分隔',
  `status` tinyint DEFAULT '1' COMMENT '1在读2停课3结课4退费',
  `deleted` tinyint DEFAULT '0',
  `org_id` bigint DEFAULT NULL COMMENT '所属校区',
  `manager_id` bigint DEFAULT NULL COMMENT '学管师用户ID',
  PRIMARY KEY (`id`),
