CREATE TABLE `sys_deploy_target` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `name` varchar(64) NOT NULL COMMENT '名称（如 腾讯云生产）',
  `host` varchar(128) NOT NULL COMMENT '服务器IP/域名',
  `ssh_port` int NOT NULL DEFAULT '22' COMMENT 'SSH端口',
  `username` varchar(32) NOT NULL DEFAULT 'root' COMMENT 'SSH用户名',
  `auth_type` tinyint NOT NULL DEFAULT '1' COMMENT '认证:1-密码 2-私钥',
  `secret` varchar(512) NOT NULL COMMENT '3DES加密的密码/私钥口令',
  `key_path` varchar(255) DEFAULT NULL COMMENT '私钥文件路径（KEY认证）',
  `remote_dir` varchar(128) NOT NULL DEFAULT '/opt/kaied' COMMENT '远端部署目录',
  `app_port` int NOT NULL DEFAULT '8080' COMMENT '应用端口',
  `web_port` int NOT NULL DEFAULT '80' COMMENT '前端端口',
  `db_password` varchar(32) NOT NULL DEFAULT 'kaied123' COMMENT '随包MySQL root密码',
  `db_mode` tinyint NOT NULL DEFAULT '1' COMMENT '数据库:1-随包MySQL 2-外部数据库',
  `db_type` varchar(16) DEFAULT 'MYSQL' COMMENT '外部数据库类型(预留,当前MYSQL)',
  `db_host` varchar(128) DEFAULT NULL COMMENT '外部数据库地址',
  `db_port` int DEFAULT '3306' COMMENT '外部数据库端口',
  `db_name` varchar(64) DEFAULT 'edu_course' COMMENT '外部数据库名',
  `db_username` varchar(64) DEFAULT NULL COMMENT '外部数据库用户名',
  `db_secret` varchar(512) DEFAULT NULL COMMENT '3DES加密的外部数据库密码',
  `last_db_test_at` datetime DEFAULT NULL COMMENT '最近数据库连接测试时间',
  `last_db_test_ok` tinyint DEFAULT NULL COMMENT '最近数据库测试结果',
  `last_db_test_msg` varchar(480) DEFAULT NULL COMMENT '最近数据库测试消息',
  `enabled` tinyint NOT NULL DEFAULT '1' COMMENT '1-启用 0-停用',
  `last_test_at` datetime DEFAULT NULL COMMENT '最近连通测试时间',
  `last_test_ok` tinyint DEFAULT NULL COMMENT '最近测试结果',
  `last_test_msg` varchar(480) DEFAULT NULL COMMENT '最近测试消息',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=14 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='发布目标服务器';
