CREATE TABLE `sys_log` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint DEFAULT NULL,
  `user_id` bigint DEFAULT NULL,
  `username` varchar(32) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `operation` varchar(128) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '操作内容',
  `method` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `params` text COLLATE utf8mb4_general_ci,
  `ip` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `duration` int DEFAULT '0' COMMENT '耗时ms',
  `status` tinyint DEFAULT '0' COMMENT '0成功 1失败',
  `error_msg` text COLLATE utf8mb4_general_ci,
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP,
  `log_type` tinyint DEFAULT '0' COMMENT '0操作日志 1登录日志',
  PRIMARY KEY (`id`),
  KEY `idx_create` (`create_time`)
) ENGINE=InnoDB AUTO_INCREMENT=1401 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='操作日志表';
