CREATE TABLE `sys_menu` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户ID(0=平台模板)',
  `parent_id` bigint NOT NULL DEFAULT '0',
  `name` varchar(32) COLLATE utf8mb4_general_ci NOT NULL COMMENT '菜单名称',
  `path` varchar(128) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '路由地址',
  `component` varchar(128) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '前端组件路径',
  `icon` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `perm` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '权限标识',
  `type` char(1) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'C' COMMENT 'M目录 C菜单',
  `sort` int NOT NULL DEFAULT '0',
  `visible` tinyint NOT NULL DEFAULT '1',
  `scope` tinyint NOT NULL DEFAULT '0' COMMENT '菜单范围:0=租户模板 1=平台专属',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=1086 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='菜单表';
