DROP TABLE IF EXISTS `sys_notice`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sys_notice` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint NOT NULL DEFAULT '1',
  `title` varchar(128) COLLATE utf8mb4_general_ci NOT NULL COMMENT '通知标题',
  `content` varchar(1000) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '通知内容',
  `notice_type` tinyint DEFAULT '0' COMMENT '0系统 1课程 2缴费',
  `level` tinyint DEFAULT '0' COMMENT '0普通 1重要 2紧急',
  `target` varchar(20) COLLATE utf8mb4_general_ci DEFAULT 'ALL' COMMENT '目标角色: ALL/EDU_ADMIN/CLASS_TEACHER/TEACHER/STUDENT',
  `target_users` varchar(512) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '指定接收用户ID(逗号分隔)',
  `create_user_id` bigint DEFAULT NULL COMMENT '创建人用户ID(本人草稿/发布始终可见)',
  `create_by` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '创建人姓名(消息历史展示)',
  `status` tinyint DEFAULT '0' COMMENT '0草稿 1已发布',
  `publish_time` datetime DEFAULT NULL,
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_tenant` (`tenant_id`)
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='系统通知表';
