--
-- Table structure for table `sys_user`
--

DROP TABLE IF EXISTS `sys_user`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sys_user` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户ID(0=平台)',
  `org_id` bigint DEFAULT NULL COMMENT '所属组织',
  `username` varchar(32) COLLATE utf8mb4_general_ci NOT NULL COMMENT '登录名',
  `password` char(32) COLLATE utf8mb4_general_ci NOT NULL COMMENT 'MD5(明文+edu)',
  `real_name` varchar(32) COLLATE utf8mb4_general_ci NOT NULL COMMENT '姓名',
  `gender` tinyint DEFAULT '1' COMMENT '1男 2女',
  `phone` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `email` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `user_type` tinyint NOT NULL COMMENT '1超管 2教管人员 3班主任 4教师 5学生',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '1启用 0停用',
  `last_login_time` datetime DEFAULT NULL,
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP,
  `avatar` mediumblob COMMENT '头像图像(直接存库)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_tenant_username` (`tenant_id`,`username`)
) ENGINE=InnoDB AUTO_INCREMENT=48 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='用户表';
/*!40101 SET character_set_client = @saved_cs_client */;

